// Determine if this is a fresh job or a revision
let folderId = '', musicId = '', editPrompt = '', watermark = '@MemesAdda', run_id = '';
let isRevision = false;
let revisionInstructions = '';
let iteration = 1;

// ── Path A: Fresh edit from Form ───────────────────────────────────────────
try {
  const form = $items('🎬 Form: New Edit Job');
  if (form.length > 0 && form[0].json['Google Drive Folder ID (clips)']) {
    folderId   = form[0].json['Google Drive Folder ID (clips)'];
    musicId    = form[0].json['Music Drive File ID (optional)'] || '';
    editPrompt = form[0].json['Edit Instructions'] || '';
    watermark  = form[0].json['Channel Watermark'] || '@MemesAdda';
    run_id     = Date.now().toString();
    isRevision = false;
    // Save fresh state to static data
    const sd = $getWorkflowStaticData('global');
    sd[run_id] = { folderId, musicId, editPrompt, watermark, iteration: 1, history: [editPrompt] };
  }
} catch(e) {}

// ── Path B: Revision request from Form ────────────────────────────────────
if (!folderId) {
  try {
    const rev = $items('✏️ Form: Request Changes');
    if (rev.length > 0 && rev[0].json['Run ID (copy from Telegram message)']) {
      run_id              = rev[0].json['Run ID (copy from Telegram message)'].trim();
      revisionInstructions = rev[0].json['What changes do you want?'] || '';
      isRevision          = true;
      // Load previous state from static data
      const sd = $getWorkflowStaticData('global');
      const prev = sd[run_id] || {};
      folderId   = prev.folderId || '';
      musicId    = prev.musicId  || '';
      watermark  = prev.watermark || '@MemesAdda';
      iteration  = (prev.iteration || 1) + 1;
      // Build cumulative edit prompt (history + new revision)
      const history = prev.history || [prev.editPrompt || ''];
      editPrompt = history[history.length - 1]; // carry forward the latest instructions
      // Update static data
      history.push(revisionInstructions);
      sd[run_id] = { ...prev, iteration, history };
    }
  } catch(e) {}
}

if (!folderId || !run_id) throw new Error('No valid edit job found. Please start a new edit or provide a valid Run ID.');
if (iteration > 10)       throw new Error('Maximum revision limit (10) reached for this job.');

return [{ json: {
  folderId, musicId, editPrompt, watermark, run_id,
  isRevision, revisionInstructions, iteration
} }];

const all = $input.all();
const videoExt = /\.(mp4|mov|avi|mkv|webm)$/i;
const clips = all
  .filter(item => videoExt.test(item.json.name || ''))
  .sort((a, b) => (a.json.name || '').localeCompare(b.json.name || '', undefined, { numeric: true }));

if (clips.length === 0) throw new Error('No video files (.mp4, .mov, .avi) found in the specified Drive folder.');

const { editPrompt, watermark, musicId, run_id, isRevision, revisionInstructions, iteration } = $('🔀 Route: New Job or Revision').first().json;

return clips.map((item, i) => ({
  json: {
    ...item.json,
    clip_index: i,
    clip_count: clips.length,
    clip_names: clips.map(c => c.json.name),
    editPrompt, watermark, musicId, run_id,
    isRevision, revisionInstructions, iteration
  }
}));

const all = $input.all();
const clipCount = all.length;
const clipNames = all.map(i => i.json.name || `Clip ${i.json.clip_index + 1}`);
const { editPrompt, watermark, musicId, run_id, isRevision, revisionInstructions, iteration } = all[0].json;
return [{ json: { clipCount, clipNames, editPrompt, watermark, musicId, run_id, isRevision, revisionInstructions, iteration } }];

