// Build the complete FFmpeg filter graph from AI-parsed edit operations
const aiRaw = $json.message?.content || $json.choices?.[0]?.message?.content || '[]';
const meta   = $('📋 Collect Clip Metadata').first().json;
let { clipCount, clipNames, watermark, musicId, run_id, iteration } = meta;
watermark = (watermark || '@MemesAdda').replace(/'/g, '');

let ops = [];
try {
  let raw = aiRaw.trim().replace(/^```[a-z]*\s*/i, '').replace(/\s*```$/i, '');
  ops = JSON.parse(raw);
} catch(e) {
  console.log('AI parse failed, using minimal defaults:', e.message);
  ops = [{ type: 'fade', in_duration: 0.5, out_duration: 0.5 }];
}

// ── Apply clip_swap operations to reorder clips ─────────────────────────────
let clipOrder = Array.from({ length: clipCount }, (_, i) => i);
for (const op of ops) {
  if (op.type === 'clip_swap') {
    const fi = op.from_index, ti = op.to_index;
    if (fi >= 0 && fi < clipOrder.length && ti >= 0 && ti < clipOrder.length) {
      [clipOrder[fi], clipOrder[ti]] = [clipOrder[ti], clipOrder[fi]];
    }
  }
}

// ── Apply clip_remove operations ────────────────────────────────────────────
const removedIndices = new Set(ops.filter(o => o.type === 'clip_remove').map(o => o.clip_index));
clipOrder = clipOrder.filter(i => !removedIndices.has(i));
const effectiveCount = clipOrder.length;

if (effectiveCount === 0) throw new Error('All clips were removed. Nothing to render.');

// ── Build per-clip speed map ─────────────────────────────────────────────────
const speedMap = {};
for (const op of ops) {
  if (op.type === 'speed') speedMap[op.clip_index] = op.speed_factor || 1.0;
}

// ── Build transition map ─────────────────────────────────────────────────────
const transMap = {};
for (const op of ops) {
  if (op.type === 'transition') transMap[op.after_clip] = op;
}

// ── Collect title/caption overlay ops ───────────────────────────────────────
const drawOps = ops.filter(o => ['title', 'caption'].includes(o.type));

// ── Fade settings ────────────────────────────────────────────────────────────
const fadeOp   = ops.find(o => o.type === 'fade');
const fadeIn   = fadeOp?.in_duration  ?? 0.8;
const fadeOut  = fadeOp?.out_duration ?? 0.8;

// ── Music volume ─────────────────────────────────────────────────────────────
const musicOp  = ops.find(o => o.type === 'music');
const musicVol = musicOp?.volume ?? 0.25;

// ── Build FFmpeg filter_complex ──────────────────────────────────────────────
const filterParts = [];
const audioLabels = [];

// Step 1: Scale + speed each EFFECTIVE clip (in reordered order)
clipOrder.forEach((origIdx, pos) => {
  const spd = speedMap[origIdx] || 1.0;
  const spdFilter = spd !== 1.0 ? `,setpts=PTS/${spd}` : '';
  filterParts.push(
    `[${origIdx}:v]scale=1080:1920:force_original_aspect_ratio=decrease,` +
    `pad=1080:1920:(ow-iw)/2:(oh-ih)/2,setsar=1,fps=30${spdFilter}[sv${pos}]`
  );
  const aFilt = spd !== 1.0
    ? `[${origIdx}:a]atempo=${Math.min(2.0, Math.max(0.5, spd)).toFixed(2)}[sa${pos}]`
    : `[${origIdx}:a]acopy[sa${pos}]`;
  filterParts.push(aFilt);
  audioLabels.push(`[sa${pos}]`);
});

// Step 2: Chain xfade transitions
let prevLabel = 'sv0';
for (let i = 1; i < effectiveCount; i++) {
  const origIdx = clipOrder[i - 1];
  const tr = transMap[origIdx] || transMap[i - 1] || { style: 'fade', duration: 0.8 };
  const dur = tr.duration || 0.8;
  const style = tr.style === 'zoomin' ? 'wipeleft' : (tr.style || 'fade');
  const outLabel = i === effectiveCount - 1 ? 'xfout' : `xf${i}`;
  filterParts.push(`[${prevLabel}][sv${i}]xfade=transition=${style}:duration=${dur}:offset=${i * 8}[${outLabel}]`);
  prevLabel = outLabel;
}

const afterJoin = effectiveCount === 1 ? 'sv0' : 'xfout';

// Step 3: Fade in/out
filterParts.push(`[${afterJoin}]fade=in:st=0:d=${fadeIn},fade=out:st=30:d=${fadeOut}[faded]`);

// Step 4: Watermark
const wmF = `drawtext=text='${watermark}':fontsize=36:fontcolor=white@0.85:x=w-text_w-20:y=20:box=1:boxcolor=0x00000066:boxborderw=8:shadowcolor=black:shadowx=2:shadowy=2`;
filterParts.push(`[faded]${wmF}[wmd]`);

// Step 5: Titles + Captions chain
let curLabel = 'wmd';
drawOps.forEach((op, idx) => {
  const txt  = (op.text || '').replace(/'/g, '');
  const yMap = { top: '80', center: '(h-text_h)/2', bottom: 'h-180' };
  const x    = '(w-text_w)/2';
  const y    = yMap[op.position] || (op.type === 'title' ? '80' : 'h-180');
  const fs   = op.fontsize || (op.type === 'title' ? 58 : 52);
  const col  = op.color || (op.type === 'title' ? 'white' : 'yellow');
  const ss   = op.start_sec || 0;
  const se   = op.end_sec   || ss + 4;
  const outL = idx === drawOps.length - 1 ? 'finalv' : `cap${idx}`;
  filterParts.push(
    `[${curLabel}]drawtext=text='${txt}':fontsize=${fs}:fontcolor=${col}:` +
    `x=${x}:y=${y}:enable='between(t,${ss},${se})':` +
    `box=1:boxcolor=0x000000bb:boxborderw=14:shadowcolor=black:shadowx=3:shadowy=3[${outL}]`
  );
  curLabel = outL;
});
if (drawOps.length === 0) filterParts.push(`[${curLabel}]copy[finalv]`);

// Step 6: Audio mix
if (musicId) {
  filterParts.push(
    `${audioLabels.join('')}concat=n=${effectiveCount}:v=0:a=1[concata];` +
    `[concata][${clipCount}:a]amix=inputs=2:weights=1 ${musicVol}:normalize=0[finala]`
  );
} else {
  filterParts.push(`${audioLabels.join('')}concat=n=${effectiveCount}:v=0:a=1[finala]`);
}

const filterComplex = filterParts.join(';');

return [{
  json: {
    filterComplex,
    clipOrder,
    effectiveCount,
    watermark, musicId, run_id, iteration,
    editOpsApplied: ops.length,
    summaryOfChanges: ops.map(o => o.type).join(', ')
  }
}];

